package com.bank.mergesorted;

import java.util.*;
import java.util.logging.*;

public class MergeSortedDemo {
    private static final Logger log = Logger.getLogger("MergeSorted");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> branchA = List.of(5000, 15000, 25000);
        List<Integer> branchB = List.of(8000, 12000, 30000);
        MergeSortedService service = new MergeSortedService();

        List<Integer> merged = service.merge(branchA, branchB);
        log.info(() -> "Merged sorted: " + merged);
    }
}

// ─── Would be in service/MergeSortedService.java ───
class MergeSortedService {
    List<Integer> merge(List<Integer> a, List<Integer> b) {
        return java.util.stream.Stream.concat(a.stream(), b.stream())  // join
            .sorted()                                                   // order combined
            .toList();
    }
}
